def mark_hotel_created_accounts(apps, schema_editor):
    """Existing staff: the invite made the login when the account appeared together with the
    invitation (same couple of minutes). Older accounts that were only attached stay False."""
    Membership = apps.get_model('memberships', 'HotelMembership')
    for m in Membership.objects.filter(invited_by__isnull=False).exclude(role='owner').select_related('user'):
        if abs(m.user.created_at - m.created_at) <= timedelta(minutes=2):
            m.account_created = True
            m.save(update_fields=['account_created'])


